using System;
using System.Collections;
using System.Linq;
using UnityEngine;
using UnityEngine.SceneManagement;
public sealed class DeliveryPersistence:MonoBehaviour {
 DeliveryManager manager;float saveAt,requestedAt=-1;bool initialized;double played;string saveId;[Min(15)]public float autosaveInterval=90;public bool Ready=>initialized;
 IEnumerator Start(){if(autosaveInterval<15)autosaveInterval=90;manager=GetComponent<DeliveryManager>();if(manager==null)yield break;manager.Restoring=true;if(manager.GetComponent<GridShiftLife>()==null)manager.gameObject.AddComponent<GridShiftLife>();GridShiftOperationsUI.Instance?.ResetSessionObservations();var data=DeliverySaveStore.Pending;DeliverySaveStore.Pending=null;bool fresh=DeliverySaveStore.StartFresh;if(data==null&&!fresh&&GridShiftProfiles.LoggedIn&&GridShiftProfiles.ActiveSlot>0&&GridShiftProfiles.Read(GridShiftProfiles.ActiveSlot,out var existing,out _))data=existing;DeliverySaveData seed=null;if(fresh&&GridShiftProfiles.LoggedIn&&GridShiftProfiles.ActiveSlot>0)GridShiftProfiles.Read(GridShiftProfiles.ActiveSlot,out seed,out _);var character=data?.character??seed?.character;saveId=data?.saveId??seed?.saveId;if(!Guid.TryParseExact(saveId,"N",out _))saveId=Guid.NewGuid().ToString("N");if(GridShiftProfiles.LoggedIn&&GridShiftProfiles.ActiveSlot>0)GridShiftTutorial.Prefix="GS.Tutorial."+GridShiftProfiles.ProfileId+"."+GridShiftProfiles.ActiveSlot+".Partida."+saveId+".";GridShiftCharacter.Restore(character);manager.GetComponent<GridShiftLife>().Restore(data?.life);GridShiftTutorial.Restore(fresh?null:data?.tutorial,fresh);DeliverySaveStore.StartFresh=false;yield return null;
 if(fresh&&WorldSession.Instance!=null){WorldSession.Instance.RestoreClock(720);WorldSession.Instance.RestoreCalendar(.375);}if(data!=null){manager.RestoreEconomy(data.money,data.orders,data.selected);manager.Progression.Restore(data.upgrades);played=data.playSeconds;var world=WorldSession.Instance;if(world!=null){world.RestoreClock(data.clock);world.RestoreCalendar(data.version>=2?data.calendarDays:data.clock/1920.0);}if(data.version>=3&&data.simulation!=null){GridShiftPerformanceSettings.SelectPreset(Mathf.Clamp(data.simulation.preset,0,2));GridShiftPerformanceSettings.Set("Pedestrians",data.simulation.pedestrians);GridShiftPerformanceSettings.Set("Traffic",data.simulation.traffic);}}
 manager.Company.Initialize(data?.company,fresh);var city=Player("SampleScene");bool old=city!=null&&city.ControlsBlocked;if(city!=null)city.BlockControls(true);
 if(data!=null){if(city!=null&&data.playerPosition.sqrMagnitude>1)Place(city,data.playerPosition,data.playerRotation);if(data.version>=3&&data.vehicles!=null&&data.vehicles.Count>0){var routes=UnityEngine.Object.FindObjectsByType<TrafficRoute>(FindObjectsSortMode.None).ToDictionary(GridShiftRouteIdentity.Of);foreach(var saved in data.vehicles){CompanyVehicle v=null;float until=Time.realtimeSinceStartup+15;while(v==null&&Time.realtimeSinceStartup<until){v=manager.AdoptSaved(saved);if(v==null)yield return null;}if(v==null){manager.Notify("Veículo "+saved.id+" aguardando modelo compatível; entrega preservada para reatribuição.");continue;}if(routes.TryGetValue(saved.routeId??"",out var route))v.driver.RestoreLogicalRoute(route,saved.nextPoint,saved.position,saved.rotation);v.RestoreSaved(saved,manager.orders.FirstOrDefault(o=>o.id==saved.orderId));}}
 foreach(var order in manager.orders)if(order.mode!=DeliveryMode.Personal&&order.status!=DeliveryStatus.Completed&&!manager.fleet.Any(v=>v!=null&&v.Order==order)){order.status=DeliveryStatus.WaitingVehicle;order.vehicleId=null;}manager.RestoreTracking(data.trackedVehicleId,data.selected);}
 manager.GetComponent<GridShiftActiveOperations>()?.Restore(data?.personalVan);manager.Restoring=false;initialized=true;saveAt=Time.unscaledTime+autosaveInterval;if(city!=null)city.BlockControls(old);if(data!=null&&(data.currentScene=="Office"||data.currentScene=="Apartment"||data.currentScene=="FactoryInterior")&&WorldSession.Instance!=null){yield return WorldSession.Instance.RequestTransition(data.currentScene,city!=null?city.transform:null);var office=Player(data.currentScene=="Office"?"Apartment":data.currentScene);if(office!=null&&data.currentScene!="Office"&&(data.currentScene!="Apartment"||data.homeLayoutVersion>=24)&&data.activePlayerPosition.sqrMagnitude>1)Place(office,data.activePlayerPosition,data.activePlayerRotation);}if(data!=null){GridShiftAudio.Play("Save_Loaded","UI",.4f);manager.Notify("Partida carregada. Empresa e operações restauradas.");}}
 static PlayerMovement Player(string scene)=>UnityEngine.Object.FindObjectsByType<PlayerMovement>(FindObjectsInactive.Include,FindObjectsSortMode.None).FirstOrDefault(p=>p.gameObject.scene.name==scene);
 static void Place(PlayerMovement player,Vector3 at,Quaternion rotation){var cc=player.GetComponent<CharacterController>();cc.enabled=false;player.transform.SetPositionAndRotation(at,rotation);Physics.SyncTransforms();cc.enabled=true;}
 void Update(){if(!initialized)return;played+=Time.unscaledDeltaTime;if(WorldSession.Instance!=null&&WorldSession.Instance.Busy)return;if(Time.unscaledTime>=saveAt||(requestedAt>=0&&Time.unscaledTime>=requestedAt)){saveAt=Time.unscaledTime+autosaveInterval;requestedAt=-1;Save();}}
 public void RequestSave(){if(initialized&&requestedAt<0)requestedAt=Time.unscaledTime+.6f;}
 public DeliverySaveData Capture(){var city=Player("SampleScene");var scene=SceneManager.GetActiveScene().name;var active=Player(scene);return new DeliverySaveData{homeLayoutVersion=24,saveId=saveId,life=manager.GetComponent<GridShiftLife>()?.Capture(),character=GridShiftCharacter.Copy(GridShiftCharacter.Current),personalVan=manager.GetComponent<GridShiftActiveOperations>()?.Capture(),tutorial=GridShiftTutorial.Capture(),profileId=GridShiftProfiles.ProfileId,slot=GridShiftProfiles.ActiveSlot,companyName=GridShiftProfiles.CompanyName,savedUtc=DateTime.UtcNow.ToString("O"),playSeconds=played,currentScene=scene=="Apartment"||scene=="FactoryInterior"?scene:"SampleScene",trackedVehicleId=manager.TrackedVehicleId,company=manager.Company.State,calendarDays=WorldSession.Instance!=null?WorldSession.Instance.CalendarDays:0,money=manager.Money,upgrades=manager.Progression.levels,clock=WorldSession.Instance!=null?WorldSession.Instance.ClockTime:0,selected=manager.SelectedId,orders=manager.orders,vehicles=manager.fleet.Where(v=>v!=null&&v.driver!=null&&v.driver.RotaAtual!=null).Select(v=>v.Capture()).ToList(),playerPosition=manager.GetComponent<GridShiftActiveOperations>()?.Van?.Driving==true?manager.GetComponent<GridShiftActiveOperations>().Van.SafeExit:city!=null?city.transform.position:Vector3.zero,playerRotation=city!=null?city.transform.rotation:Quaternion.identity,activePlayerPosition=manager.GetComponent<GridShiftActiveOperations>()?.Van?.Driving==true?manager.GetComponent<GridShiftActiveOperations>().Van.SafeExit:active!=null?GridShiftHomeBath.SavePosition(active):Vector3.zero,activePlayerRotation=active!=null?active.transform.rotation:Quaternion.identity,simulation=new SimulationSaveData{preset=GridShiftPerformanceSettings.Preset,pedestrians=GridShiftPerformanceSettings.PedestrianDensity,traffic=GridShiftPerformanceSettings.TrafficDensity}};}
 public bool Save(){if(!initialized||manager==null||manager.GetComponent<GridShiftLife>()?.Dead==true||manager.Restoring||(WorldSession.Instance!=null&&WorldSession.Instance.Busy))return false;if(string.IsNullOrEmpty(DeliverySaveStore.OverridePath)&&(!GridShiftProfiles.LoggedIn||GridShiftProfiles.ActiveSlot<1))return false;bool ok=DeliverySaveStore.Write(Capture());if(ok){saveAt=Time.unscaledTime+autosaveInterval;requestedAt=-1;GridShiftSaveThumbnail.Capture(DeliverySaveStore.PathName);GridShiftTutorial.Record("save");}return ok;}
 void OnApplicationQuit(){if(initialized)Save();}
}






